  $org=$repo->organizationForUser((int)($_SESSION['organization_id']??0),(int)$user['id']);
  if($action==='request_shift'){
   if(!$org) throw new InvalidArgumentException('Select an organization first.');
   $result=$scheduling->requestShift((int)$org['id'],(int)$org['membership_id'],(int)$_POST['shift_id']);
   flash($result['result']==='eligible'?'Shift request submitted.':'Shift request submitted for supervisor approval.'); redirect_to('schedule');
  }
  if(!$org||!in_array($org['role'],['owner','admin'],true)) throw new InvalidArgumentException('Only owners and administrators can change organization structure.');
  $oid=(int)$org['id'];
  if($action==='add_location'){ $repo->addLocation($oid,(int)$user['id'],(string)$_POST['name']); flash('Location added.'); }
  elseif($action==='add_department'){ $repo->addDepartment($oid,(int)$user['id'],(string)$_POST['name'],(int)($_POST['location_id']??0),(string)($_POST['color']??'#2563eb')); flash('Department added.'); }
  elseif($action==='add_position'){ $repo->addPosition($oid,(int)$user['id'],(string)$_POST['name'],(int)($_POST['department_id']??0),(string)($_POST['category']??'other'),(string)($_POST['color']??'#7756d9')); flash('Custom position added.'); }
  elseif($action==='add_supervisor_group'){ $repo->addSupervisorGroup($oid,(int)$user['id'],(string)$_POST['name'],(int)($_POST['department_id']??0),(array)($_POST['supervisor_membership_ids']??[])); flash('Supervisor group added and automatic routing updated.'); }
  elseif($action==='create_invitation'){ $appUrl=rtrim((string)Config::get('APP_URL',''),'/'); $inviteUrl=$appUrl!==''?$appUrl.'/index.php?route=invite':url_for('invite'); $_SESSION['invitation_link']=$repo->createInvitation($oid,(int)$user['id'],$_POST,$inviteUrl); flash('Invitation created. Copy its secure link below.'); redirect_to('team'); }
  elseif($action==='update_staff'){ $scheduling->updateStaff($oid,(int)$user['id'],$_POST); flash('Staff workforce profile updated.'); redirect_to('team'); }
  elseif($action==='add_catalog_item'){ $scheduling->addCatalogItem($oid,(int)$user['id'],(string)$_POST['catalog_type'],$_POST); flash('Operational resource added.'); }
  elseif($action==='create_shift'){ $scheduling->createShift($oid,(int)$user['id'],$_POST); flash('Open shift created with eligibility rules.'); redirect_to('schedule'); }
  elseif($action==='add_coverage'){ $scheduling->addCoverage($oid,(int)$user['id'],$_POST); flash('Coverage assignment added.'); redirect_to('coverage'); }
  redirect_to('organization');
 }catch(Throwable $e){ $error=$e instanceof InvalidArgumentException?$e->getMessage():'Atlas could not complete that action.'; }
}

